/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_hrm_certificate_warning_dept_id` BEFORE INSERT ON `hrm_certificate_warning` FOR EACH ROW SET NEW.dept_id = IFNULL(NEW.dept_id, (SELECT e.dept_id FROM hrm_employee e WHERE e.id = NEW.employee_id)) */;;
