DROP TABLE IF EXISTS `hrm_company_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_company_profile` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '企业档案编号',
  `name` varchar(255) NOT NULL COMMENT '企业名称快照（对外展示名，允许与租户名不同）',
  `short_name` varchar(128) DEFAULT NULL COMMENT '企业简称',
  `logo` varchar(500) DEFAULT NULL COMMENT '企业 Logo 文件地址',
  `industry` varchar(128) DEFAULT NULL COMMENT '所属行业',
  `scale` varchar(64) DEFAULT NULL COMMENT '企业规模，如 1-49 人 / 100-499 人 / 1000 人以上',
  `nature` varchar(64) DEFAULT NULL COMMENT '企业性质，如 民营 / 国企 / 合资 / 外资',
  `summary` varchar(2000) DEFAULT NULL COMMENT '企业简介',
  `products` text COMMENT '产品与服务介绍，JSON 数组：[{"name":"","intro":"","image":""}]',
  `address` varchar(255) DEFAULT NULL COMMENT '企业地址（文本）',
  `area_id` int DEFAULT NULL COMMENT '企业所在地区编号（省市区）',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '企业地址经度（BD09 百度坐标系）',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '企业地址纬度（BD09 百度坐标系）',
  `website` varchar(255) DEFAULT NULL COMMENT '企业官网',
  `established_date` date DEFAULT NULL COMMENT '成立日期（工商信息，查不到留空）',
  `registered_capital` varchar(64) DEFAULT NULL COMMENT '注册资本，如 5000 万元人民币（查不到留空）',
  `credit_code` varchar(64) DEFAULT NULL COMMENT '统一社会信用代码（查不到留空，严禁编造）',
  `legal_person` varchar(64) DEFAULT NULL COMMENT '法定代表人（查不到留空，严禁编造）',
  `data_source` varchar(64) DEFAULT NULL COMMENT '资料来源：企业官网 / 公开工商信息 / 平台演示数据',
  `data_source_url` varchar(500) DEFAULT NULL COMMENT '资料来源链接，便于追溯核实',
  `verified` bit(1) NOT NULL DEFAULT b'0' COMMENT '信息是否已人工核实',
  `sort` int DEFAULT NULL COMMENT '展示排序',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0 已发布，1 已下架',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '所属租户编号（一租户一档）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hrm_company_profile_tenant` (`tenant_id`,`deleted`),
  KEY `idx_hrm_company_profile_name` (`name`),
  KEY `idx_hrm_company_profile_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 企业档案表';
/*!40101 SET character_set_client = @saved_cs_client */;

