INSERT INTO `hrm_company_profile` VALUES (1,'西北恒泰新材料有限公司','西北恒泰','\"C:\\Users\\31107\\Desktop\\logo\\1.png\"','新材料','100-499 人','民营','专注油气管道用高性能复合材料的研发与生产，产品覆盖管道补强材料、耐蚀合金复合板与密封绝缘材料，长期为西北地区长输管线工程提供配套。设有独立的材料性能检测实验室，具备来料检验与成品型式试验能力。','[{\"image\":\"\",\"intro\":\"用于在役管道缺陷修复与补强，施工无需停输\",\"name\":\"管道补强复合材料\"},{\"image\":\"\",\"intro\":\"适用于高含硫油气环境的管道内衬与设备制造\",\"name\":\"耐蚀合金复合板\"},{\"image\":\"\",\"intro\":\"用于管道法兰、螺纹连接处的防腐密封\",\"name\":\"密封与绝缘材料\"}]','陕西省延安市安塞区高新技术产业开发区兴业路 12 号',610624,109.322100,36.861200,NULL,NULL,NULL,NULL,NULL,'平台演示数据',NULL,_binary '\0',1,0,'admin','2026-09-20 22:28:04','80036','2026-09-22 08:53:02',_binary '\0',2001),(2,'锦程树脂化工科技有限公司','锦程树脂',NULL,'树脂化工','100-499 人','民营','以环氧树脂、不饱和聚酯树脂为核心产品，为防腐涂料与玻璃钢制品企业提供基础树脂原料，配套供应固化剂与助剂。生产装置实行连续化控制，产品批次稳定性高。','[{\"name\":\"环氧树脂\",\"intro\":\"用于重防腐涂料与玻璃钢衬里，附着力强、耐化学介质\",\"image\":\"\"},{\"name\":\"不饱和聚酯树脂\",\"intro\":\"用于玻璃钢管道、储罐缠绕成型\",\"image\":\"\"},{\"name\":\"固化剂与助剂\",\"intro\":\"配套树脂使用的固化体系与流平助剂\",\"image\":\"\"}]','陕西省延安市安塞区高新技术产业开发区创新路 8 号',610624,109.331500,36.868800,NULL,NULL,NULL,NULL,NULL,'平台演示数据',NULL,_binary '\0',2,0,'admin','2026-09-20 22:28:04','admin','2026-09-20 22:28:04',_binary '\0',2002),(3,'蓝盾涂料原料集团','蓝盾涂料',NULL,'涂料原料','100-499 人','民营','从事重防腐涂料用原料的研发与供应，主营熔结环氧粉末、聚氨酯保温原料与无机富锌基料，为管道防腐涂装企业提供稳定的原料保障与配方技术支持。','[{\"name\":\"熔结环氧粉末\",\"intro\":\"用于管道 3PE 与单层环氧粉末涂装\",\"image\":\"\"},{\"name\":\"聚氨酯保温原料\",\"intro\":\"用于聚氨酯发泡保温管道生产\",\"image\":\"\"},{\"name\":\"无机富锌基料\",\"intro\":\"用于储罐与钢结构重防腐底漆\",\"image\":\"\"}]','陕西省延安市安塞区高新技术产业开发区科技路 26 号',610624,109.325800,36.872100,NULL,NULL,NULL,NULL,NULL,'平台演示数据',NULL,_binary '\0',3,0,'admin','2026-09-20 22:28:04','admin','2026-09-20 22:28:04',_binary '\0',2003),(4,'隆达橡塑材料股份有限公司','隆达橡塑',NULL,'橡塑材料','100-499 人','民营','生产管道防腐用橡塑制品，主营辐射交联热收缩带、聚乙烯夹克料与橡胶密封件，产品应用于长输管道补口防腐与保温管道外护层生产。','[{\"name\":\"辐射交联热收缩带\",\"intro\":\"用于管道焊口补口防腐，密封性好、施工便捷\",\"image\":\"\"},{\"name\":\"聚乙烯夹克料\",\"intro\":\"用于保温管道外护层挤出成型\",\"image\":\"\"},{\"name\":\"橡胶密封圈\",\"intro\":\"用于管道接口与阀门密封\",