DROP TABLE IF EXISTS `hrm_employee_contract`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_employee_contract` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '合同编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `type` tinyint DEFAULT NULL COMMENT '合同类型',
  `start_time` datetime DEFAULT NULL COMMENT '合同开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '合同结束时间',
  `term` int DEFAULT NULL COMMENT '期限',
  `status` tinyint DEFAULT NULL COMMENT '合同状态',
  `sign_company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签约公司',
  `sign_time` datetime DEFAULT NULL COMMENT '合同签订日期',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `expire_remind` bit(1) DEFAULT NULL COMMENT '是否到期提醒',
  `sort` int DEFAULT NULL COMMENT '排序',
  `file_urls` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件地址数组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `dept_id` bigint DEFAULT NULL COMMENT '所属部门编号（冗余自 hrm_employee.dept_id，用于部门数据权限）',
  `template_id` bigint DEFAULT NULL COMMENT '合同模板编号',
  `source_offer_id` bigint DEFAULT NULL COMMENT '来源 Offer 编号',
  `work_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作内容（劳务内容）',
  `work_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作地点',
  `work_task` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作任务（以完成任务为期限时）',
  `pay_mode` tinyint DEFAULT NULL COMMENT '计薪方式：1 月薪，2 日薪，3 计件',
  `pay_amount` decimal(12,2) DEFAULT NULL COMMENT '计薪金额/单价',
  `pay_unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计薪单位，如 元/月、元/日、元/件',
  `pay_day` tinyint DEFAULT NULL COMMENT '每月发薪日',
  `commercial_insurance` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商业保险说明',
  `attendance_mode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考勤方式',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_employee_contract_employee_id` (`employee_id`) USING BTREE,
  KEY `idx_hrm_employee_contract_status_end_time` (`status`,`end_time`,`employee_id`) USING BTREE,
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2010 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工合同表';
