--
-- Table structure for table `hrm_performance_assessment_quota`
--

DROP TABLE IF EXISTS `hrm_performance_assessment_quota`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_assessment_quota` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `assessment_id` bigint NOT NULL COMMENT '员工绩效考核编号',
  `dimension_id` bigint NOT NULL COMMENT '员工绩效考核维度编号',
  `preset` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否预置指标',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标名称',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标说明',
  `standard` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评分标准',
  `weight` decimal(10,2) DEFAULT '100.00' COMMENT '指标权重',
  `score_type` tinyint DEFAULT NULL COMMENT '评分类型',
  `target_value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标值',
  `actual_value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际值',
  `self_score` decimal(10,2) DEFAULT '0.00' COMMENT '自评分',
  `reviewer_score` decimal(10,2) DEFAULT '0.00' COMMENT '评分人分数',
  `final_score` decimal(10,2) DEFAULT '0.00' COMMENT '最终分',
  `sort` int DEFAULT '0' COMMENT '排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_quota_dimension_id` (`dimension_id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_quota_assessment_id` (`assessment_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工绩效考核指标表';
/*!40101 SET character_set_client = @saved_cs_client */;

