--
-- Table structure for table `hrm_performance_assessment_stage`
--

DROP TABLE IF EXISTS `hrm_performance_assessment_stage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_assessment_stage` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `assessment_id` bigint NOT NULL COMMENT '员工绩效考核编号',
  `type` tinyint NOT NULL COMMENT '业务阶段类型',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段名称',
  `handler_employee_id` bigint DEFAULT NULL COMMENT '实际处理员工编号',
  `handler_user_id` bigint DEFAULT NULL COMMENT '实际处理后台用户编号',
  `rater_type` tinyint DEFAULT NULL COMMENT '评分人类型',
  `weight` decimal(10,2) DEFAULT NULL COMMENT '评分权重快照',
  `scoring_type` tinyint DEFAULT NULL COMMENT '评分方式',
  `visible_content` tinyint DEFAULT NULL COMMENT '可见内容',
  `required_setting` bit(1) DEFAULT NULL COMMENT '评语是否必填',
  `reject_authority` bit(1) DEFAULT NULL COMMENT '是否允许驳回',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0 未处理，1 已处理，2 待处理，3 已驳回，4 处理中，5 已申诉',
  `score` decimal(10,2) DEFAULT NULL COMMENT '阶段综合得分',
  `result_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段结果等级',
  `comment` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段评语',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次驳回原因',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `deadline_time` datetime DEFAULT NULL COMMENT '截止时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_stage_assessment_id` (`assessment_id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_stage_handler` (`handler_user_id`,`type`,`status`) USING BTREE,
  KEY `idx_hrm_performance_assessment_stage_deadline` (`type`,`status`,`deadline_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工绩效考核阶段表';
/*!40101 SET character_set_client = @saved_cs_client */;

