--
-- Table structure for table `hrm_performance_plan`
--

DROP TABLE IF EXISTS `hrm_performance_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划名称',
  `cycle_type` tinyint DEFAULT NULL COMMENT '考核周期类型',
  `cycle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考核周期',
  `quarter` tinyint DEFAULT NULL COMMENT '季度',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考核说明',
  `scopes` json NOT NULL COMMENT '考评范围配置',
  `assessment_template_id` bigint NOT NULL COMMENT '考核模板编号',
  `assessment_config` json NOT NULL COMMENT '考核配置快照',
  `result_template_id` bigint NOT NULL COMMENT '结果模板编号',
  `result_config` json NOT NULL COMMENT '结果配置快照',
  `quota_setting_type` tinyint NOT NULL DEFAULT '1' COMMENT '指标制定类型：1 系统制定，2 员工填写',
  `target_confirmation` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否开启目标确认',
  `target_confirmation_stage` json DEFAULT NULL COMMENT '目标确认节点配置',
  `review_stages` json NOT NULL COMMENT '评分阶段配置',
  `result_audit` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否开启结果审核',
  `result_audit_stages` json DEFAULT NULL COMMENT '结果审核节点配置',
  `result_confirmation` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否开启结果确认',
  `appeal_stages` json DEFAULT NULL COMMENT '申诉处理节点配置',
  `appeal_timeout_days` int NOT NULL DEFAULT '2' COMMENT '绩效申诉超期天数',
  `appeal_timeout_action` tinyint NOT NULL DEFAULT '1' COMMENT '绩效申诉超期处理动作：1 自动拒绝，2 自动通过',
  `sync_to_salary` bit(1) DEFAULT b'0' COMMENT '是否同步到薪资',
  `paid_for_month` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计薪月份',
  `stage_type` tinyint DEFAULT '0' COMMENT '当前业务阶段类型',
  `status` tinyint DEFAULT '2' COMMENT '计划状态',
  `operation_type` tinyint DEFAULT NULL COMMENT '当前可执行操作类型：1 开启评分，2 发起绩效面谈，3 归档',
  `terminate_time` datetime DEFAULT NULL COMMENT '终止时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_plan_name` (`name`) USING BTREE,
  KEY `idx_hrm_performance_plan_template_id` (`assessment_template_id`) USING BTREE,
  KEY `idx_hrm_performance_plan_result_template_id` (`result_template_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 绩效计划表';
/*!40101 SET character_set_client = @saved_cs_client */;

