INSERT INTO `hrm_recruit_agent_analysis` VALUES (1,6,'RESUME_ANALYZE',2,2021242,'bc0d73592f10d42cf92ffaeaecd80636e862bd13f5e55a31ccd6d095eaf5c587',45,'{\"overallScore\":45,\"dimensions\":[{\"key\":\"COMPLETENESS\",\"score\":40,\"comment\":\"简历信息不完整，多处关键信息缺失\",\"evidence\":[{\"field\":\"experiences\",\"note\":\"工作经历中缺少具体职位、部门、描述和成就信息\"},{\"field\":\"projects\",\"note\":\"项目经验完全空白\"}]},{\"key\":\"CLARITY\",\"score\":50,\"comment\":\"简历内容表述不够清晰，关键信息模糊\",\"evidence\":[{\"field\":\"position\",\"note\":\"工作经历中未明确具体职位名称\"},{\"field\":\"description\",\"note\":\"工作描述内容为空，无法了解工作职责\"}]},{\"key\":\"PROFESSIONALISM\",\"score\":40,\"comment\":\"专业性与目标职位匹配度不高\",\"evidence\":[{\"field\":\"skills\",\"note\":\"技能列表与财务职位关联性不强，缺乏财务相关技能\"},{\"field\":\"expectedPostName\",\"note\":\"期望职位为预算员/造价员，但目标职位为财务，存在方向不一致\"}]},{\"key\":\"JOB_MATCH\",\"score\":50,\"comment\":\"与目标财务职位匹配度一般，专业背景和技能存在差距\",\"evidence\":[{\"field\":\"major\",\"note\":\"专业为材料科学与工程，与财务专业背景差异较大\"},{\"field\":\"postName\",\"note\":\"目标职位为财务，但简历中未展示相关财务工作经验\"}]}],\"strengths\":[\"有明确的工作意向和期望城市\",\"具备一定的项目管理技能\",\"教育背景完整，学历符合要求\"],\"missingInfo\":[\"工作经历中的具体职位和部门信息\",\"工作职责和成就描述\",\"项目经验完全缺失\",\"财务相关技能未展示\",\"工作经历中的行业信息不完整\"],\"risks\":[\"专业背景与目标财务职位不匹配\",\"缺乏财务相关工作经验\",\"技能与财务职位需求不符\",\"简历信息不完整，难以评估实际能力\"],\"suggestions\":[{\"module\":\"WORK_EXPERIENCE\",\"fieldPath\":\"position\",\"advice\":\"补充具体的工作职位名称\",\"reason\":\"明确职位有助于评估与目标职位的匹配度\"},{\"module\":\"WORK_EXPERIENCE\",\"fieldPath\":\"description\",\"advice\":\"详细描述工作职责和内容\",\"reason\":\"完整的工作描述能展示实际能力和经验\"},{\"module\":\"SKILLS\",\"fieldPath\":\"skills\",\"advice\":\"增加财务相关技能，如会计软件、财务分析等\",\"reason\":\"目标职位为财务，需要展示相关专业技能\"},{\"module\":\"JOB_INTENTION\",\"fieldPath\":\"expectedPostName\",\"advice\":\"明确职业发展方向，考虑是否与财务职位一致\",\"reason\":\"期望职位与目标职位不一致会影响求职成功率\"}]}','有明确的工作意向和期望城市','resume-analyze-v1','glm-4.5-air',NULL,'81054','2026-09-18 15:06:54','81054','2026-09-18 15:06:54',_binary '\0',0),(2,7,'RESUME_ANALYZE',2,2021242,'bc0d73592f10d42cf92ffaeaecd80636e862bd13f5e55a31ccd6d095eaf5c587',45,'{\"overallScore\":45,\"dimensions\":[{\"key\":\"COMPLETENESS\",\"score\":40,\"comment\":\"简历信息不完整，多处关键信息缺失\",\"evidence\":[{\"field\":\"experiences\",\"note\":\"工作经验部分缺少具体职位、部门、描述和成就信息\"},{\"field\":\"projects\",\"note\":\"项目经验部分完全为空\"}]},{\"key\":\"CLARITY\",\"score\":50,\"comment\":\"简历表述不够清晰，关键信息模糊\",\"evidence\":[{\"field\":\"position\",\"note\":\"工作经验中未明确具体职位名称\"},{\"field\":\"description\",\"note\":\"工作描述部分为空，无法了解工作内容\"}]},{\"key\":\"PROFESSIONALISM\",\"score\":50,\"comment\":\"专业性与目标职位匹配度不高\",\"evidence\":[{\"field\":\"skills\",\"note\":\"技能列表中缺少财务相关技能，与财务职位要求不符\"},{\"field\":\"expectedPostName\",\"note\":\"期望职位为预算员/造价员，但目标职位为财务，存在明显差异\"}]},{\"key\":\"JOB_MATCH\",\"score\":40,\"comment\":\"与目标财务职位匹配度低\",\"evidence\":[{\"field\":\"expectedPostName\",\"note\":\"期望职位为预算员/造价员，与目标财务职位不符\"},{\"field\":\"skills\",\"note\":\"技能列表中缺少财务相关技能，无法满足财务职位要求\"},{\"field\":\"major\",\"note\":\"专业为材料科学与工程，与财务专业背景不符\"}]}],\"strengths\":[\"有明确的工作意向\",\"具备一定的工程相关技能\",\"教育背景完整\"],\"missingInfo\":[\"工作经验中的具体职位、部门信息\",\"工作职责和成就描述\",\"项目经验\",\"财务相关技能\",\"自我介绍\"],\"risks\":[\"期望职位与目标职位不匹配\",\"缺乏财务相关经验和技能\",\"工作经历描述不完整，无法评估实际能力\"],\"suggestions\":[{\"module\":\"JOB_INTENTION\",\"fieldPath\":\"expectedPostName\",\"advice\":\"重新评估职业目标，明确是否转向财务方向\",\"reason\":\"当前期望的预算员/造价员职位与目标财务职位存在明显差异\"},{\"module\":\"WORK_EXPERIENCE\",\"fieldPath\":\"position\",\"advice\":\"补充完整工作经历中的具体职位和部门信息\",\"reason\":\"当前工作经历信息不完整，无法评估实际工作能力\"},{\"module\":\"SKILLS\",\"fieldPath\":\"skills\",\"advice\":\"增加财务相关技能，如会计软件、财务分析等\",\"reason\":\"目标职位为财务，当前技能列表缺乏相关内容\"},{\"module\":\"WORK_EXPERIENCE\",\"fieldPath\":\"description\",\"advice\":\"详细描述工作职责和成就，特别是与财务相关的内容\",\"reason\":\"工作描述空白，无法展示与目标职位相关的经验和能力\"}]}','有明确的工作意向','resume-analyze-v1','glm-4.5-air',NULL,'81054','2026-09-18 15:07:08','81054','2026-09-18 15:07:08',_binary '\0',0),(3,8,'RESUME_ANALYZE',2,2021242,'bc0d73592f10d42cf92ffaeaecd80636e862bd13f5e55a31ccd6d095eaf5c587',45,'{\"overallScore\":45,\"dimensions\":[{\"key\":\"COMPLETENESS\",\"score\":40,\"comment\":\"简历基本信息完整，但工作经历和项目经验部分内容缺失\",\"evidence\":[{\"field\":\"experiences\",\"note\":\"工作经历中缺少具体职位、部门、描述和成就信息\"},{\"field\":\"projects\",\"note\":\"项目经验部分完全为空\"}]},{\"key\":\"CLARITY\",\"score\":50,\"comment\":\"职业目标明确，但工作经历描述不够清晰\",\"evidence\":[{\"field\":\"expectedPostName\",\"note\":\"期望职位明确为预算员/造价员\"},{\"field\":\"position\",\"note\":\"工作经历中缺少具体职位描述\"}]},{\"key\":\"PROFESSIONALISM\",\"score\":40,\"comment\":\"技能与期望职位不匹配，缺乏财务相关专业知识\",\"evidence\":[{\"field\":\"skills\",\"note\":\"技能列表中缺少财务、会计、预算等核心技能\"},{\"field\":\"expectedPostName\",\"note\":\"期望职位为预算员/造价员，但技能与该职位要求不符\"}]},{\"key\":\"JOB_MATCH\",\"score\":50,\"comment\":\"专业背景与期望行业相关，但工作经验与目标职位不匹配\",\"evidence\":[{\"field\":\"major\",\"note\":\"材料科学与工程专业与防腐保温行业相关\"},{\"field\":\"position\",\"note\":\"工作经历中未显示财务或预算相关职位经验\"}]}],\"strengths\":[\"有明确的工作意向，期望在防腐保温行业担任预算员/造价员\",\"具备材料科学与工程的专业背景，与期望行业相关\",\"工作经验年限较长，有实际工作经历\"],\"missingInfo\":[\"工作经历中缺少具体职位、部门、工作描述和成就\",\"项目经验部分完全为空\",\"技能列表中缺少财务、会计、预算等核心技能\",\"未提供任何与预算员/造价员相关的证书或培训经历\"],\"risks\":[\"技能与期望职位不匹配，缺乏财务相关专业知识\",\"工作经历描述不完整，无法评估实际工作能力\",\"没有展示任何与预算员/造价员相关的项目经验\"],\"suggestions\":[{\"module\":\"WORK_EXPERIENCE\",\"fieldPath\":\"experiences\",\"advice\":\"补充工作经历中的具体职位、部门、工作描述和成就\",\"reason\":\"完整的工作经历有助于评估候选人与目标职位的匹配度\"},{\"module\":\"SKILLS\",\"fieldPath\":\"skills\",\"advice\":\"增加财务、会计、预算软件操作等相关技能\",\"reason\":\"预算员/造价员职位需要专业的财务和预算知识\"},{\"module\":\"PROJECT_EXPERIENCE\",\"fieldPath\":\"projects\",\"advice\":\"添加与预算或成本控制相关的项目经验\",\"reason\":\"项目经验能更好地展示候选人在目标职位上的实际能力\"}]}','有明确的工作意向，期望在防腐保温行业担任预算员/造价员','resume-analyze-v1','glm-4.5-air',NULL,'81054','2026-09-18 15:07:42','81054','2026-09-18 15:07:42',_binary '\0',0),(4,9,'JOB_MATCH',2,2021242,'bc0d73592f10d42cf92ffaeaecd80636e862bd13f5e55a31ccd6d095eaf5c587',30,'{\"overallScore\":30,\"dimensions\":[{\"key\":\"SKILL\",\"score\":20,\"comment\":\"技能与财务岗位要求不匹配，缺乏财务相关技能\",\"evidence\":[{\"field\":\"skills\",\"note\":\"简历中技能为办公软件、工程制图、项目管理、施工组织，无财务相关技能\"}]},{\"key\":\"EXPERIENCE\",\"scor