INSERT INTO `hrm_recruit_favorite` VALUES (1,81059,'COMPANY',2020,2020,'秦川化工产业园发展有限公司',NULL,'榆林市','当前公开招聘 200 个职位，欢迎了解企业招聘机会。',NULL,'81059','2026-09-20 11:18:55','81059','2026-09-20 11:18:55',_binary '\0',0),(2,81059,'POST',2021239,2017,'会计',NULL,NULL,NULL,NULL,'81059','2026-09-20 11:19:00','81059','2026-09-20 22:31:16',_binary '',0),(3,81054,'POST',2021240,2018,'高级会计',NULL,NULL,NULL,NULL,'81054','2026-09-20 16:36:03','81054','2026-09-20 16:36:03',_binary '\0',0),(4,81059,'POST',2021242,2001,'财务',NULL,NULL,NULL,NULL,'81059','2026-09-20 22:31:09','81059','2026-09-20 22:31:15',_binary '',0),(5,81059,'POST',2021225,2005,'涂料研发工程师',NULL,NULL,NULL,NULL,'81059','2026-09-20 22:31:58','81059','2026-09-20 22:31:58',_binary '\0',0),(6,81059,'POST',2021220,2004,'涂料研发工程师',NULL,NULL,NULL,NULL,'81059','2026-09-20 22:31:59','81059','2026-09-20 22:31:59',_binary '\0',0),(7,81060,'POST',2021222,2005,'生产操作工',NULL,NULL,NULL,NULL,'81060','2026-09-21 16:19:01','81060','2026-09-21 16:19:01',_binary '\0',0),(8,81060,'COMPANY',2025,2025,'天信管业科技集团有限公司','管道防腐保温','延安市','天信管业科技集团有限公司位于陕西省延安市安塞高新技术产业开发区，成立于 2014 年元月，占地 83 亩，总建筑面积 44900 平方米。公司建有四个标准化厂房、一个数字化生产调度中心、三个研究所，以及延安市防腐保温重点实验室与「科学家+工程师」队伍；现有正式职工 87 人，其中高级专业技术职称 7 人。公司具有防水防腐保温工程专业承包一级资质，是国家高新技术企业、陕西省创新型中小企业、陕西省和延安市「专精特新」中小企业，中石油防腐保温入围一级承包企业，累计取得发明型专利 12 项、实用型专利 30 项。主营业务涵盖管道防腐、保温、保冷及防腐材料的开发应用，石油专用管道修复再制造，管道检测，以及信息安全与信息技术服务。',NULL,'81060','2026-09-21 16:19:18','81060','2026-09-21 16:19:19',_binary '',0),(9,81060,'COMPANY',2020,2020,'秦川化工产业园发展有限公司','化工园区运营','榆林市','负责化工产业园区的开发建设与运营管理，为入园企业提供土地、标准厂房、公用工程与安全环保配套服务。',NULL,'81060','2026-09-21 16:20:00','81060','2026-09-21 16:20:00',_binary '\0',0),(10,81059,'POST',2021242,2001,'财务',NULL,NULL,NULL,NULL,'81059','2026-09-22 08:00:41','81059','2026-09-22 08:00:41',_binary '\0',0);
